Official solution: \url{https://www.imo-official.org/problems/IMO2010SL.pdf}

The official solution works in this more general setting.
We present Solution 1.

To show that $n c^2$ is attainable, we take $x_i = c$ if $i$ is even and $x_i = 0$ if $i$ is odd.
The details are left to the reader as an exercise.
The converse follows from the following claim, which implies
\[ \sum_{i = 1}^{2n} x_i x_{i + 2} = \sum_{i = 1}^n (x_{2i} x_{2i + 2} + x_{2i + 1} x_{2i + 3}) \leq \sum_{i = 1}^n c^2 = n c^2. \]

\begin{claim}
Let $w, x, y, z \in R$ such that $x, y \geq 0$ and $w + x + y, x + y + z \leq 2c$.
Then $wy + xz \leq c^2$.
\end{claim}
\begin{proof}
Indeed, $wy + xz \leq (2c - (x + y)) y + x (2c - (x + y)) = (x + y)(2c - (x + y))$.
Then AM-GM inequality yields the claim.
\end{proof}

Official solution: \url{https://www.imo-official.org/problems/IMO2010SL.pdf}

We follow Solution 2 of the official solution.
We proceed through a series of lemmas.
The first two lemmas only rely on the first equation, $f(g(x)) = f(x) + 1$.

\begin{lemma}\label{2010a6-1}
There exists $a \in \N$ such that $f(\N) = \{a, a + 1, a + 2, \ldots\}$.
\end{lemma}
\begin{proof}
Take $a$ to be the smallest element of $f(\N)$, which is non-empty since it contains $f(0)$.
For any $a \in f(\N)$, we have $a + 1 = f(x) + 1 = f(g(x))$ for some $x \in \N$, and thus $a + 1 \in f(\N)$.
It follows by induction that $k \in f(\N)$ for any $k \geq a$, and minimality yields $k \notin f(\N)$ for $k < a$.
\end{proof}

\begin{lemma}\label{2010a6-2}
For any $x, y \in \N$, if $g(x) = g(y)$, then $f(x) = f(y)$.
\end{lemma}
\begin{proof}
Indeed, $g(x) + 1 = g(f(x)) = g(f(y)) = g(y) + 1$.
\end{proof}

By symmetry, $g(\N)$ is also of form $\{b, b + 1, b + 2, \ldots\}$ for some $b \in \N$.
Also, $f(x) = f(y)$ implies $g(x) = g(y)$.
Now we let $a = \min f(\N)$ and $b = \min g(\N)$.

\begin{lemma}\label{2010a6-3}
We have $f(a) > a$.
\end{lemma}
\begin{proof}
Clearly $f(a) \in f(\N)$, which yields $f(a) \geq a$.
But if $f(a) = a$, then $g(a) = g(f(a)) = g(a) + 1$.
\end{proof}

\begin{lemma}\label{2010a6-4}
For any $k, m \in f(\N)$, $f(k) = f(m)$ implies $k = m$.
\end{lemma}
\begin{proof}
Write $k = f(x)$ and $m = f(y)$ for some $x, y \in \N$.
Lemma~\ref{2010a6-4} leads to $g(k) = g(m)$, and thus
\[ g(f(x)) = g(f(y)) \implies g(x) = g(y) \implies f(x) = f(y) \implies k = m, \]
    as desired.
\end{proof}

\begin{lemma}\label{2010a6-5}
We have $a = b$.
\end{lemma}
\begin{proof}
By symmetry, we may assume that $a \leq b$.
Since $g(\N) = \{b, b + 1, \ldots\}$, to prove $a = b$, it suffices to prove that $a \in g(\N)$.
Indeed, since $f(a) > a$, we can find $x \in \N$ such that $f(a) = f(x) + 1 = f(g(x))$.
But $a \in f(\N)$, and $g(x) \in f(\N)$ as well since $g(x) \geq b \geq a$.
Thus, Lemma~\ref{2010a6-4} yields $a = g(x)$, as desired.
\end{proof}

\begin{lemma}\label{2010a6-6}
We have $f(a) = a + 1$.
\end{lemma}
\begin{proof}
By Lemma~\ref{2010a6-3}, it suffices to show that $f(a) < a + 2$.

Suppose for the sake of contradiction that $f(a) \geq a + 2$.
Then we can write $f(a) = f(x) + 2$ for some $x \in \N$.
Also, since $f(\N) = g(\N)$, we can write $g(x) = f(y)$ for some $y \in \N$.
Note that $f(a) = f(x) + 2 = f(g(g(x)))$.
Since $a, g(g(x)) \geq a$, we have $a, g(g(x)) \in f(\N)$.
Lemma~\ref{2010a6-4} yields
\[ a = g(g(x)) = g(f(y)) = g(y) + 1 \geq a + 1, \]
    which is a contradiction.
\end{proof}

Note that by symmetry, we also have $g(a) = a + 1$.

Finally, we prove that $f = g$.
First, it suffices to prove that $f(x) = g(x) = x + 1$ for $x \geq a$.
Indeed, for $x < a$, $f(x) \geq a$ would yield $f(x) + 1 = g(f(x)) = g(x) + 1$.

To prove $f(x) = g(x) = x + 1$ for $x \geq a$, we proceed by induction on $x$.
The base case $x = a$ has already been solved.
For induction step, given $x \in \N$ such that $f(x) = g(x) = x + 1$, we have
\[ f(x + 1) = f(g(x)) = g(x) + 1 = x + 2, \]
    and symmetry yields $g(x + 1) = x + 2$.
Induction step is complete; we are done.

text:
Let $f, g : \N \to \N$ be functions such that $f(g(x)) = f(x) + 1$ and $g(f(x)) = g(x) + 1$ for all $x \in \N$.
Prove that $f = g$.



\subsection*{Solution}

Official solution: \url{https://www.imo-official.org/problems/IMO2010SL.pdf}

We follow Solution 2 of the official solution.
We proceed through a series of lemmas.
The first two lemmas only rely on the first equation, $f(g(x)) = f(x) + 1$.

\begin{lemma}\label{2010a6-1}
There exists $a \in \N$ such that $f(\N) = \{a, a + 1, a + 2, \ldots\}$.
\end{lemma}
\begin{proof}
Take $a$ to be the smallest element of $f(\N)$, which is non-empty since it contains $f(0)$.
For any $a \in f(\N)$, we have $a + 1 = f(x) + 1 = f(g(x))$ for some $x \in \N$, and thus $a + 1 \in f(\N)$.
It follows by induction that $k \in f(\N)$ for any $k \geq a$, and minimality yields $k \notin f(\N)$ for $k < a$.
\end{proof}

\begin{lemma}\label{2010a6-2}
For any $x, y \in \N$, if $g(x) = g(y)$, then $f(x) = f(y)$.
\end{lemma}
\begin{proof}
Indeed, $g(x) + 1 = g(f(x)) = g(f(y)) = g(y) + 1$.
\end{proof}

By symmetry, $g(\N)$ is also of form $\{b, b + 1, b + 2, \ldots\}$ for some $b \in \N$.
Also, $f(x) = f(y)$ implies $g(x) = g(y)$.
Now we let $a = \min f(\N)$ and $b = \min g(\N)$.

\begin{lemma}\label{2010a6-3}
We have $f(a) > a$.
\end{lemma}
\begin{proof}
Clearly $f(a) \in f(\N)$, which yields $f(a) \geq a$.
But if $f(a) = a$, then $g(a) = g(f(a)) = g(a) + 1$.
\end{proof}

\begin{lemma}\label{2010a6-4}
For any $k, m \in f(\N)$, $f(k) = f(m)$ implies $k = m$.
\end{lemma}
\begin{proof}
Write $k = f(x)$ and $m = f(y)$ for some $x, y \in \N$.
Lemma~\ref{2010a6-4} leads to $g(k) = g(m)$, and thus
\[ g(f(x)) = g(f(y)) \implies g(x) = g(y) \implies f(x) = f(y) \implies k = m, \]
    as desired.
\end{proof}

\begin{lemma}\label{2010a6-5}
We have $a = b$.
\end{lemma}
\begin{proof}
By symmetry, we may assume that $a \leq b$.
Since $g(\N) = \{b, b + 1, \ldots\}$, to prove $a = b$, it suffices to prove that $a \in g(\N)$.
Indeed, since $f(a) > a$, we can find $x \in \N$ such that $f(a) = f(x) + 1 = f(g(x))$.
But $a \in f(\N)$, and $g(x) \in f(\N)$ as well since $g(x) \geq b \geq a$.
Thus, Lemma~\ref{2010a6-4} yields $a = g(x)$, as desired.
\end{proof}

\begin{lemma}\label{2010a6-6}
We have $f(a) = a + 1$.
\end{lemma}
\begin{proof}
By Lemma~\ref{2010a6-3}, it suffices to show that $f(a) < a + 2$.

Suppose for the sake of contradiction that $f(a) \geq a + 2$.
Then we can write $f(a) = f(x) + 2$ for some $x \in \N$.
Also, since $f(\N) = g(\N)$, we can write $g(x) = f(y)$ for some $y \in \N$.
Note that $f(a) = f(x) + 2 = f(g(g(x)))$.
Since $a, g(g(x)) \geq a$, we have $a, g(g(x)) \in f(\N)$.
Lemma~\ref{2010a6-4} yields
\[ a = g(g(x)) = g(f(y)) = g(y) + 1 \geq a + 1, \]
    which is a contradiction.
\end{proof}

Note that by symmetry, we also have $g(a) = a + 1$.

Finally, we prove that $f = g$.
First, it suffices to prove that $f(x) = g(x) = x + 1$ for $x \geq a$.
Indeed, for $x < a$, $f(x) \geq a$ would yield $f(x) + 1 = g(f(x)) = g(x) + 1$.

To prove $f(x) = g(x) = x + 1$ for $x \geq a$, we proceed by induction on $x$.
The base case $x = a$ has already been solved.
For induction step, given $x \in \N$ such that $f(x) = g(x) = x + 1$, we have
\[ f(x + 1) = f(g(x)) = g(x) + 1 = x + 2, \]
    and symmetry yields $g(x + 1) = x + 2$.
Induction step is complete; we are done.

solution:
Official solution: \url{https://www.imo-official.org/problems/IMO2010SL.pdf}

We present the official solution below.
We generalize a bit so that a much larger range of values of $A$ work.
More precisely, denote $P_0 = 1$ and $P_{n + 1} = 2^{P_n}$ for all $n \geq 1$.
Then we claim that any $A < 4P_{16}$ works.

Represent the stack using an $N$-tuple of non-negative integers.
Given $\mathbf{n}, \mathbf{p} \in \N^N$, we denote $\mathbf{n} \to \mathbf{p}$ if there is a sequence of (possibly empty) operations that change $\mathbf{n}$ to $\mathbf{p}$.
The main observations are as follows.

\begin{lemma}
$(b + k, c) \to (b, c + 2k)$ for any $b, c, k \in \N$.
\end{lemma}
\begin{proof}
This follows by simple induction on $k$.
\end{proof}

\begin{lemma}
$(k + a, n, n) \to (k, n + 2^a, n)$ for any $k, a, n \in \N$ with $a \geq 1$.
\end{lemma}
\begin{proof}
The first step is to observe that
\[ (k + 1, n + m, n) \to (k + 1, n, n + 2m) \to (k, n + 2m, n). \]
Now by induction, we have $(k + a, n + m, n) \to (k, n + 2^a m, n)$ for any $k, a, m, n \in \N$.
For $a \geq 1$, we get
\[ (k + a, n, n) \to (k + a - 1, n + 2, n) \to (k, n + 2^a, n). \]
\end{proof}

\begin{lemma}
$(a, n, n, n) \to (0, n + P_a, n, n)$ for any $a \geq 1$ and $n \in \N$.
\end{lemma}
\begin{proof}
Start with $(a, n, n, n) \to (a - 1, n + 2, n, n)$, and note that $P_1 = 2$.
Now for any $k, m, n \in \N$, the previous observation yields
\[ (k + 1, n + m, n, n) \to (k + 1, n, n + 2^m, n) \to (k, n + 2^m, n, n). \]
The rest is just induction on $a$.
\end{proof}

\begin{lemma}
For any $N \geq 6$ and $A < 4N$ with $A \neq 1$, the following holds:
\begin{itemize}
    \item   If $A \not\equiv 3 \pmod{4}$, then $(N, 0, 0) \to (0, 0, A)$.
    \item   If $A \equiv 3 \pmod{4}$, then $(N, 1, 1) \to (0, 0, A)$.
\end{itemize}
\end{lemma}
\begin{proof}
We can write $A = 4K + r$ for some $K < N$ and $r \in \{0, 1, 2, 3\}$.
To prove the lemma, we bash one-by-one.
For $A = 4K$ with $K < N$,
\[ (N, 0, 0) \to (K, 0, 0) \to (0, 2K, 0) \to (0, 0, 4K). \]
For $A = 4K + 1$ with $0 < K < N$,
\[ (N, 0, 0) \to (K + 1, 0, 0) \to (K, 2, 0) \to (K, 1, 2) \to (K - 1, 2, 1) \to (K - 1, 0, 5) \to (0, 0, 4K + 1). \]
For $A = 4K + 2$ with $K \leq N - 2$,
\[ (N, 0, 0) \to (K + 2, 0, 0) \to (K + 1, 2, 0) \to (K, 0, 2) \to (0, 0, 4K + 2). \]
For $A = 4(N - 1) + 2 = 4N - 2$, since $N \geq 6$, we get
\[ (N, 0, 0) \to (N - 1, 0, 0) \to (N - 5, 16, 0) \to (N - 5, 14, 4) \to (N - 6, 4, 14) \to (N - 6, 0, 22) \to (0, 0, 4N - 2). \]
For $A = 4K + 3$ with $K < N$,
\[ (N, 1, 1) \to (K, 1, 1) \to (K, 0, 3) \to (0, 4K + 3). \]
The proof is complete.
\end{proof}

Now notice that $(1, 1) \to (0, 3)$ and $(1, 0, 3) \to (0, 3, 0)$.
By repeating this process, we get
\[ (1, 1, 1, 1, 1, 1) \to (0, 3, 0, 0, 0, 0) \to (0, 0, P_3 = 16, 0, 0, 0) \to (0, 0, 0, P_{16}, 0, 0). \]
We also have
\[ (1, 1, 1, 1, 1, 1) \to (0, 3, 1, 1, 1, 1) \to (0, 0, 17, 1, 1, 1) \to (0, 0, 0, P_{17} + 1, 1, 1) \to (0, 0, 0, P_{16}, 1, 1). \]
By the last lemma above, we get $(1, 1, 1, 1, 1, 1) \to (0, 0, 0, 0, 0, A)$ whenever $A < 4P_{16}$ and $A \neq 1$.
Finally, for $A = 1$, just notice that
\[ (1, 1, 1, 1, 1, 1) \to (1, 1, 1, 0, 3, 1) \to (0, 3, 0, 0, 0, 1) \to (0, 0, 0, 0, 0, 1). \]
This is enough for the original problem, as $2010^{2010^{2010}} < P_6 < 4P_{16}$.



\subsection*{Implementation details}

Instead of actually using $N$-tuple to represent stack state, we use lists.

